use verus::prelude::*;

verus! {

    /// Returns `(true, idx)` if `a[idx]` is the first odd element of `a`,
    /// or `(false, 0)` if there is no odd element.
    fn find_first_odd(a: &[i32]) -> (bool, usize)
        ensures(|result: (bool, usize)| 
            match result {
                (false, _) =>
                    // no odd found ⇒ all entries are even
                    forall(|i: usize| i < a.len() ==> a[i] % 2 == 0),
                (true, idx) =>
                    // idx is in‐bounds, odd, and everything before is even
                    idx < a.len() &&
                    a[idx] % 2 != 0 &&
                    forall(|j: usize| j < idx ==> a[j] % 2 == 0)
            }
        )
    {
        let n = a.len();
        let mut i: usize = 0;

        // Search for the first odd element
        while i < n
            invariant(i <= n)
            invariant(forall(|j: usize| j < i ==> a[j] % 2 == 0))
            decreases(n - i)
        {
            // If we found an odd element at i, return immediately
            if a[i] % 2 != 0 {
                return (true, i);
            }
            // Otherwise advance i
            i += 1;
        }

        // No odd element found
        (false, 0)
    }
}